public interface Valued {
    double value();
}

public record MonetaryAmount(String currency, double amount) implements Valued {
    // Compact Constructor for validation
    public MonetaryAmount {
        Objects.requireNonNull(currency, "Currency must not be null");
        if (amount < 0.0) {
            throw new IllegalArgumentException("Amount cannot be negative");
        }
        // Note: No field assignments (this.amount = amount) are written here!
    }

    @Override
    public double value() {
        return amount;
    }
}
